	$('.jq-toggle').click(function(){
		if ($(this).hasClass('on')) {
			$(this).removeClass('on');
		} else {
			$(this).addClass('on');
		}
	});
	/* TAP */
	$('.tapt').click(function(){
		$(this).siblings('.tapt').removeClass('on');
		$(this).addClass('on');
